	('48e597c1-bc7b-44a9-843d-73f8201d221a', 'ab44e12b-f5fe-408d-9fb7-74d4514ae34f', 'Trâm Tracy', 'https://nwaiwnnczgdpcyzdvcxs.supabase.co/storage/v1/object/public/submissions/1784820832223-c52ln5j.PDF', '2026-07-23 15:33:55.868851+00', '9fb48dae-703e-4fcf-9d8b-2eab33c112b0', '99', '<p>Tout est vrai! Bravo</p>', NULL, NULL),
	('c645e3a3-5d6c-47ce-97f8-e92302237c91', 'a349ce41-9bd9-4851-abc3-69e9da758361', 'Phương Anh', NULL, '2026-06-22 07:06:57.754381+00', '1d27bda1-0cc9-4ca3-bcdf-f77cce400274', '100', '<p>Bài khóa chép đầy đủ, đúng chính tả. Cố gắng luyện đọc nhée</p>', 'https://nwaiwnnczgdpcyzdvcxs.supabase.co/storage/v1/object/public/submissions/1782112015316-a0oxhqm.docx', 100.00),
	('408fc593-9086-4d7b-816c-6dc036588485', '52a2bfba-94c0-457f-8ae3-7cf36595b2d9', 'Bảo Trân', 'https://nwaiwnnczgdpcyzdvcxs.supabase.co/storage/v1/object/public/submissions/1783149822959-hwo5ln5.pdf', '2026-07-04 07:23:48.031991+00', 'df65cc0d-d138-449c-9f55-b0bf99d72d81', '80', '<p><strong>I. 28/30 pts</strong></p><p>Sai một câu Vrai/Faux nè, lỗi này cần đọc kĩ lại bài.</p><p><strong>II. 31/40 pts</strong></p><ul><li><p>Trừ nửa điểm vì chưa thuộc bài phần Futur Proche. Nhớ kĩ sự khác biệt giữa Futur Proche và Passé Récent nhá</p></li></ul><p><strong>III. 21/30 pts</strong></p><ul><li><p>- Viết đúng định dạng email, đủ 4 ý chính theo yêu cầu đề bài. (5 pts)</p></li><li><p>- Đề yêu cầu tối thiểu 120 từ nhưng bài viết hơi dài, khá nguy hiểm. Tốt nhất nên viết khoảng 130-140 từ là an toàn. (3 pts)</p></li><li><p>- Vẫn còn một số lỗi ngữ pháp đáng kể như Passé Composé . Ex: j''ai acheté, j''ai commencé,.... (5.5 pts)</p></li><li><p>- Từ vựng khá, có các từ nối và đa dạng hóa câu. (5 pts)</p></li><li><p>- Chính tả và dấu câu đúng. (2.5 pts)</p></li></ul><p><strong><em>Total: 80/100</em></strong></p>', NULL, NULL),
	('d4cd574a-0cc1-40eb-ab7c-d79c8e5c6e3c', '6b1353e6-6386-4d2f-b8fa-ae041016ca6e', 'Phương Anh', 'https://nwaiwnnczgdpcyzdvcxs.supabase.co/storage/v1/object/public/submissions/1782112809739-irg99fb.pdf', '2026-06-22 07:20:13.094241+00', '1d27bda1-0cc9-4ca3-bcdf-f77cce400274', '100', '<p>Cố gắng học từ vựng nha&lt;3 Bài tập thì làm oke roài nhưng mà cố gắng nhớ từ vựng nữa là xonggg</p>', NULL, 100.00),
	('7f625377-91f1-4b07-a589-731aae0cc4da', 'ea2bc692-888f-47fa-9495-5368904d91cc', 'Phương Anh', 'https://nwaiwnnczgdpcyzdvcxs.supabase.co/storage/v1/object/public/submissions/1782312895773-n5yi48w.pdf', '2026-06-24 14:54:59.709614+00', '1d27bda1-0cc9-4ca3-bcdf-f77cce400274', '99', '<p>Trừ 1 điểm vì hông có dấu nhe hihihi</p>', NULL, 99.00),
