	('20757c93-aa6f-4c5a-97ab-72cdc4f7ec0e', 'a436b829-9762-4722-945a-b8312dcd7815', 'Bảo Trân', 'https://nwaiwnnczgdpcyzdvcxs.supabase.co/storage/v1/object/public/submissions/1781952004320-fmr1can.pdf', '2026-06-20 10:40:07.234266+00', 'df65cc0d-d138-449c-9f55-b0bf99d72d81', '50', '<p>Faire l''attention aux vocabulaires!!</p>', NULL, 50.00),
